// Handle both {data: []} and [] response formats
const result = [];

items.forEach(item => {
  const data = item.json.data || item.json || [];
  if (Array.isArray(data)) {
    data.forEach(lead => {
      result.push({json: lead});
    });
  } else {
    result.push({json: data});
  }
});

return result;

// Filter to only status=2 leads first
const status2Leads = items.filter(item => {
  const lead = item.json;
  return lead.status === "2" || lead.status === 2;
});

console.log(`Found ${status2Leads.length} leads with status=2`);

if (status2Leads.length === 0) {
  return [{
    json: {
      message: "No status=2 leads found",
      toDeleteList: [],
      summary: { totalLeads: 0, noWebsite: 0, duplicates: 0, toDelete: 0 }
    }
  }];
}

// Track leads to delete
const toDeleteIds = new Set();
const toDeleteList = [];
const summary = {
  totalLeads: status2Leads.length,
  noWebsite: 0,
  duplicates: 0,
  toDelete: 0
};

// 1. Mark no-website leads
status2Leads.forEach(item => {
  const lead = item.json;
  if (!lead.website || lead.website.trim() === '') {
    toDeleteIds.add(lead.id);
    toDeleteList.push({
      id: lead.id,
      name: lead.name,
      reason: 'no-website',
      email: lead.email || 'N/A',
      phone: lead.phonenumber || 'N/A'
    });
    summary.noWebsite++;
  }
});

// 2. Email deduplication
const emailMap = new Map();
status2Leads.forEach(item => {
  const lead = item.json;
  if (toDeleteIds.has(lead.id)) return; // Skip if already marked

  if (lead.email && lead.email.trim() !== '') {
    const email = lead.email.toLowerCase().trim();
    if (emailMap.has(email)) {
      const existing = emailMap.get(email);
      const duplicateId = lead.id > existing.id ? lead.id : existing.id;

      if (!toDeleteIds.has(duplicateId)) {
        toDeleteIds.add(duplicateId);
        toDeleteList.push({
          id: duplicateId,
          name: duplicateId === lead.id ? lead.name : existing.name,
          reason: `duplicate-email: ${email}`,
          email: email,
          phone: duplicateId === lead.id ? (lead.phonenumber || 'N/A') : (existing.phone || 'N/A')
        });
        summary.duplicates++;
      }

      // Keep the one with lower ID
      if (lead.id < existing.id) {
        emailMap.set(email, {
          id: lead.id,
          name: lead.name,
          email: lead.email,
          phone: lead.phonenumber
        });
      }
    } else {
      emailMap.set(email, {
        id: lead.id,
        name: lead.name,
        email: lead.email,
        phone: lead.phonenumber
      });
    }
  }
});

summary.toDelete = toDeleteList.length;

console.log(`Analysis complete: ${summary.noWebsite} no-website, ${summary.duplicates} duplicates, ${summary.toDelete} total to delete`);

// Create output array
const output = [];

// First item: summary
output.push({
  json: {
    message: "Lead cleanup analysis complete",
    summary: summary,
    toDeleteList: toDeleteList,
    _isDeleteItem: false  // Add this line
  }
});

// Add individual delete items with _isDeleteItem flag
toDeleteList.forEach(deleteItem => {
  output.push({
    json: {
      id: deleteItem.id,
      name: deleteItem.name,
      reason: deleteItem.reason,
      email: deleteItem.email,
      phone: deleteItem.phone,
      _isDeleteItem: true
    }
  });
});

console.log(`Output: ${output.length} total items (1 summary + ${toDeleteList.length} delete items)`);
console.log(`First delete item:`, output[1]?.json);

return output;

const s = ($items('Mark Duplicates & No-Website', 0, 0)[0]?.json) || {};
const list = s.toDeleteList || [];
return [{
  json: {
    timestamp: new Date().toISOString(),
    action: 'Lead Cleanup - Status 2 Auto-Delete',
    plannedDeletes: list.length,
    deletedIds: list.map(x => x.id),
    summary: s.summary
  }
}];
